import { useEffect, useMemo, useRef, useState } from 'react';
import { ArrowLeft, ArrowRight, Bell, BookOpen, Bookmark, CalendarDays, Check, CheckCircle2, ChevronDown, ChevronRight, Clock3, FileText, Filter, Headphones, Home as HomeIcon, Lightbulb, ListChecks, MessageCircle, Mic, MoreHorizontal, Play, RotateCcw, Search, Send, Sparkles, Star, Trophy, UserRound, Users, Volume2, X } from 'lucide-react';
import { apps, asset, courses, people, questions, tasks, type Course, type CourseKind, type Task } from './mock';

type MainTab = 'home' | 'courses' | 'whale' | 'tasks' | 'my';
type Message = { side: 'me' | 'ai'; text: string; time: string };
const mainTabs: { id: MainTab; label: string; Icon: typeof HomeIcon }[] = [
  { id: 'home', label: '首页', Icon: HomeIcon }, { id: 'courses', label: '课程', Icon: BookOpen }, { id: 'whale', label: '鲸小智', Icon: MessageCircle }, { id: 'tasks', label: '任务', Icon: ListChecks }, { id: 'my', label: '我的', Icon: UserRound },
];
const initials = { learn: '学习', train: '训练', exam: '考试' };
const courseAction = { learn: '开始学习', train: '开始训练', exam: '开始考试' };
const getCourse = (id: string) => courses.find(c => c.id === id) || courses[0];
const getTask = (id: string) => tasks.find(t => t.id === id) || tasks[0];
const now = () => new Date().toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit', hour12: false });
const readStore = <T,>(key: string, fallback: T): T => { try { const raw = localStorage.getItem(key); return raw ? JSON.parse(raw) as T : fallback; } catch { return fallback; } };

function useRoute() {
  const [route, setRoute] = useState(location.hash.replace(/^#/, '') || '/home');
  useEffect(() => { const sync = () => setRoute(location.hash.replace(/^#/, '') || '/home'); addEventListener('hashchange', sync); return () => removeEventListener('hashchange', sync); }, []);
  const go = (path: string) => { location.hash = path; setRoute(path); window.scrollTo(0, 0); };
  const back = () => { if (history.length > 1) history.back(); else go('/home'); };
  const [path, query = ''] = route.split('?');
  return { path, params: new URLSearchParams(query), go, back };
}

function Progress({ value, className = '' }: { value: number; className?: string }) { return <div className={`progress ${className}`}><i style={{ width: `${Math.max(0, Math.min(100, value))}%` }} /></div>; }
function SectionTitle({ title, action, onAction }: { title: string; action?: string; onAction?: () => void }) { return <div className="section-title"><h2>{title}</h2>{action && (onAction ? <button onClick={onAction}>{action}<ChevronRight size={16} /></button> : <span className="section-note">{action}</span>)}</div>; }
function Topbar({ title, back, action }: { title: string; back: () => void; action?: React.ReactNode }) { return <header className="topbar"><button aria-label="返回" className="icon-button" onClick={back}><ArrowLeft size={23} /></button><strong>{title}</strong><div className="topbar-action">{action}</div></header>; }
function BottomNav({ active, go }: { active: MainTab; go: (route: string) => void }) { return <nav className="bottom-nav" aria-label="主导航">{mainTabs.map(({ id, label, Icon }) => <button key={id} className={active === id ? 'active' : ''} onClick={() => go(`/${id}`)}><Icon size={23} strokeWidth={active === id ? 2.4 : 1.8} /><span>{label}</span></button>)}</nav>; }
function Page({ children, tab, go, className = '' }: { children: React.ReactNode; tab?: MainTab; go: (route: string) => void; className?: string }) { return <div className={`page ${tab ? 'has-nav' : ''} ${className}`}>{children}{tab && <BottomNav active={tab} go={go} />}</div>; }
function FixedAction({ children, onClick, disabled }: { children: React.ReactNode; onClick: () => void; disabled?: boolean }) { return <footer className="fixed-action"><button className="primary-button" onClick={onClick} disabled={disabled}>{children}</button></footer>; }
function Empty({ title, hint, action, onAction }: { title: string; hint: string; action?: string; onAction?: () => void }) { return <div className="empty"><CheckCircle2 size={34} /><strong>{title}</strong><p>{hint}</p>{action && <button onClick={onAction}>{action}</button>}</div>; }

function CourseCard({ course, onClick }: { course: Course; onClick: () => void }) { return <button className="course-card" onClick={onClick}>
  <div className="course-cover"><img className="cover-back" src={course.cover} alt="" /><img className="cover-front" src={course.cover} alt="" />{course.badge && <span className="cover-tag">{course.badge}</span>}</div>
  <div className="course-card-body"><strong>{course.title}</strong><p>{course.summary}</p><div className="course-card-meta"><span>{course.progress ? `${course.progress}% 已完成` : `${course.count} ${course.kind === 'train' ? '个场景' : course.kind === 'exam' ? '道试题' : '个课时'}`}</span><span><Clock3 size={13} />{course.duration}</span></div></div>
</button>; }
function Recommendation({ course, go }: { course: Course; go: (route: string) => void }) { return <button className="recommendation" onClick={() => go(`/course/${course.id}`)}>
  <div><span className="eyebrow">为你推荐</span><strong>{course.title}</strong><p>从这门课程开始，逐步提升岗位能力</p><small><Clock3 size={15} />约 {course.duration} · {course.count} {course.kind === 'train' ? '个场景' : course.kind === 'exam' ? '道试题' : '个课时'}</small></div>
  <img src={asset('home-resume-hero.webp')} alt="" /><span className="recommendation-cta">{courseAction[course.kind]}<ChevronRight size={17} /></span>
</button>; }

function HomePage({ go }: { go: (route: string) => void }) {
  const [banner, setBanner] = useState(0);
  const banners = [{ image: 'home-banner.webp', title: '让 AI 成为你的工作伙伴', sub: '每天进步一点点' }, { image: 'home-resume-hero.webp', title: '学会表达，练好服务', sub: '从今天的任务开始' }];
  useEffect(() => { const id = setInterval(() => setBanner(b => (b + 1) % banners.length), 4800); return () => clearInterval(id); }, []);
  return <Page tab="home" go={go} className="home-page">
    <header className="home-header"><div className="brand"><span className="brand-mark">鲸</span><strong>鲸智<span>智训</span></strong></div><div className="header-tools"><button aria-label="搜索课程" onClick={() => go('/search')}><Search /></button><button aria-label="站内消息" onClick={() => go('/messages')}><Bell /><i /></button></div></header>
    <div className="home-scroll">
      <button className="home-carousel" onClick={() => go('/courses')}><img key={banner} src={asset(banners[banner].image)} alt="" /><span className="carousel-copy"><strong>{banners[banner].title}</strong><small>{banners[banner].sub}</small></span><span className="carousel-dots">{banners.map((_, i) => <i key={i} className={banner === i ? 'active' : ''} />)}</span></button>
      <section className="surface-section todo-section"><SectionTitle title="今日待办 (2)" action="查看全部" onAction={() => go('/tasks')} /><div className="todo-list"><button onClick={() => go('/task/task-1')}><span className="todo-icon blue"><FileText size={23} /></span><span className="todo-main"><strong>完成新员工岗位能力提升任务</strong><small>学习、训练和考试内容待完成</small><em><Clock3 size={13} />明日截止</em></span><span className="todo-cta">去完成<ChevronRight size={16} /></span></button><button onClick={() => go('/task/task-2')}><span className="todo-icon green"><Users size={23} /></span><span className="todo-main"><strong>家庭宽带营销任务</strong><small>完成指定课程与训练</small><em><Clock3 size={13} />5 天后到期</em></span><span className="todo-cta">去完成<ChevronRight size={16} /></span></button></div></section>
      <button className="resume-card" onClick={() => go('/task/task-1')}><div className="resume-copy"><span className="eyebrow">继续上次任务</span><strong>新员工岗位能力提升任务</strong><p>接着完成上次的学习内容</p><div className="resume-progress"><Progress value={50} /><b>50%</b></div><small>上次学习：10 分钟前</small></div><img src={asset('home-resume-hero.webp')} alt="" /><span className="resume-action">继续学习<ChevronRight size={17} /></span></button>
      <section className="home-courses"><SectionTitle title="福建福宝专区" action="查看更多课程" onAction={() => go('/courses')} /><div className="course-grid">{courses.filter(c => c.kind === 'learn').slice(0, 4).map(course => <CourseCard key={course.id} course={course} onClick={() => go(`/course/${course.id}`)} />)}</div></section>
    </div>
  </Page>;
}

function CourseCenter({ go }: { go: (route: string) => void }) {
  const [kind, setKind] = useState<CourseKind>('learn'); const [status, setStatus] = useState<'todo' | 'done'>('todo'); const [subtype, setSubtype] = useState<'human' | 'follow' | 'speech'>('human'); const [category, setCategory] = useState('全部'); const [search, setSearch] = useState(''); const [sort, setSort] = useState(false);
  const categories = ['全部', '营销拓展', '客户服务', '业务办理', '网络安全', '综合素养'];
  const visible = courses.filter(c => c.kind === kind && (kind !== 'train' || c.subtype === subtype) && (status === 'done' ? c.progress === 100 : c.progress < 100) && (category === '全部' || c.category === category) && c.title.includes(search));
  const recommend = courses.find(c => c.kind === kind && (kind !== 'train' || c.subtype === subtype) && c.progress < 100) || courses.find(c => c.kind === kind)!;
  return <Page tab="courses" go={go} className="course-page"><div className="center-hero"><div><h1>课程中心</h1><p>AI 赋能成长，成就更好的你</p></div><img src={asset('course-center-hero.png')} alt="" /></div>
    <div className="main-tabs">{(['learn','train','exam'] as const).map(item => <button key={item} className={kind === item ? 'selected' : ''} onClick={() => { setKind(item); setStatus('todo'); setCategory('全部'); setSearch(''); }}>{initials[item]}</button>)}</div>
    <main className="page-gutter course-center-content"><div className="course-search"><label><Search size={18} /><input value={search} onChange={e => setSearch(e.target.value)} placeholder={`搜索${kind === 'exam' ? '考试' : '课程'}`} /></label><button onClick={() => setSort(!sort)}><Filter size={17} />{sort ? '最新排序' : '推荐排序'}</button></div>
      {kind === 'train' && <div className="training-filters"><div className="training-mode"><strong>训练方式</strong>{([['human','人机训练'],['follow','跟读练习'],['speech','演讲训练']] as const).map(([id,label]) => <button key={id} className={subtype === id ? 'selected' : ''} onClick={() => { setSubtype(id); setStatus('todo'); }}>{label}</button>)}</div><div className="category-scroll">{categories.map(item => <button key={item} className={category === item ? 'selected' : ''} onClick={() => setCategory(item)}>{item}<small>{item === '全部' ? courses.filter(c => c.kind === 'train' && c.subtype === subtype).length : courses.filter(c => c.kind === 'train' && c.subtype === subtype && c.category === item).length}</small></button>)}</div></div>}
      <Recommendation course={recommend} go={go} />
      <div className="listing-head"><h2>{kind === 'learn' ? '全部课程' : kind === 'train' ? '精选训练' : '全部考试'}</h2><div className="status-switch"><button className={status === 'todo' ? 'selected' : ''} onClick={() => setStatus('todo')}>{kind === 'learn' ? '待学' : kind === 'train' ? '待训练' : '待考'}</button><button className={status === 'done' ? 'selected' : ''} onClick={() => setStatus('done')}>已完成</button></div></div>
      {visible.length ? <div className="course-grid">{(sort ? [...visible].reverse() : visible).map(c => <CourseCard key={c.id} course={c} onClick={() => go(`/course/${c.id}`)} />)}</div> : <Empty title="当前没有符合条件的课程" hint="可切换分类或清空搜索查看其他内容" action="清空筛选" onAction={() => { setCategory('全部'); setSearch(''); }} />}
    </main>
  </Page>;
}

function TaskCard({ task, go }: { task: Task; go: (route: string) => void }) { return <button className="task-card" onClick={() => go(`/task/${task.id}`)}><div className="task-card-top"><strong>{task.title}</strong><span className={`status ${task.status === '已完成' ? 'success' : task.status === '进行中' ? 'blue' : 'warning'}`}>{task.status}</span></div><div className="task-dates"><Clock3 size={14} />有效期 {task.start} 至 {task.due}{task.status !== '已完成' && <em>{task.id === 'task-1' ? '明日截止' : task.id === 'task-2' ? '剩余5天' : '剩余16天'}</em>}</div><div className="task-composition"><span><b>学</b>{task.learn} 门</span><span><b>训</b>{task.train} 门</span><span><b>考</b>{task.exam} 门</span></div><div className="task-progress-label"><span>已完成 {task.done}/{task.total} 门课程</span></div><Progress value={task.done / task.total * 100} /><div className="task-card-footer">{task.status === '已完成' ? '查看任务' : task.status === '进行中' ? '继续任务' : '开始任务'}<ChevronRight size={16} /></div></button>; }
function TaskCenter({ go }: { go: (route: string) => void }) { const [status, setStatus] = useState<'todo'|'done'>('todo'); const [search, setSearch] = useState(''); const [filter, setFilter] = useState(false); const visible = tasks.filter(t => (status === 'done' ? t.status === '已完成' : t.status !== '已完成') && t.title.includes(search) && (!filter || t.status === '进行中'));
  return <Page tab="tasks" go={go} className="task-page"><div className="simple-hero"><h1>任务中心</h1><p>学习、训练、考试任务，一站处理</p></div><main className="page-gutter"><div className="task-overview"><div><strong>任务概览</strong><small>管理员指派的任务</small></div><div><small>待完成</small><b>3</b></div><div><small>即将到期</small><b>2</b></div><div><small>已完成</small><b>1</b></div></div><div className="search-line"><Search size={18} /><input value={search} onChange={e => setSearch(e.target.value)} placeholder="搜索任务名称" /></div><div className="task-list-controls"><div className="plain-tabs"><button className={status === 'todo' ? 'selected' : ''} onClick={() => setStatus('todo')}>待办</button><button className={status === 'done' ? 'selected' : ''} onClick={() => setStatus('done')}>已完成</button></div><button className={filter ? 'filter selected' : 'filter'} onClick={() => setFilter(!filter)}><Filter size={17} />{filter ? '进行中' : '筛选'}</button></div><div className="task-list">{visible.length ? visible.map(t => <TaskCard key={t.id} task={t} go={go} />) : <Empty title="没有找到任务" hint="试试调整关键词或清除筛选条件" action="清空筛选" onAction={() => { setSearch(''); setFilter(false); }} />}</div></main></Page>;
}

function TaskDetail({ task, go, back }: { task: Task; go: (route: string) => void; back: () => void }) {
  const courseList = task.courseIds.map(getCourse);
  const firstOpen = task.done >= task.learn ? 'train' : 'learn';
  const [stage, setStage] = useState<CourseKind>(firstOpen);
  const stageCourses = courseList.filter(c => c.kind === stage);
  return <Page go={go} className="detail-page"><Topbar title="任务详情" back={back} /><div className="task-detail-hero"><div className="task-detail-copy"><span className="eyebrow">综合任务 · 按阶段完成</span><h1>{task.title}</h1><div className="inline-progress"><small>整体进度 {task.done}/{task.total}</small><Progress value={task.done / task.total * 100} /><b>{Math.round(task.done / task.total * 100)}%</b></div><p><Clock3 size={14} />{task.due} 截止 · {task.status === '已完成' ? '已完成' : task.id === 'task-1' ? '剩余 1 天' : '按时完成'}　<Users size={14} />32 人参与</p></div><img src={asset('task-check-illustration.jpg')} alt="" /></div><div className="stage-tabs">{(['learn','train','exam'] as const).map((item, index) => { const total = courseList.filter(c => c.kind === item).length; const completed = courseList.filter(c => c.kind === item && c.progress === 100).length; return <button key={item} className={stage === item ? 'selected' : ''} onClick={() => setStage(item)}><span className="stage-num">0{index+1}</span><span><strong>{initials[item]}</strong><small>{completed === total ? '已完成' : completed ? '进行中' : index > 0 && task.done === 0 ? '待解锁' : '待开始'}</small></span><em>{completed}/{total}</em></button>; })}</div><main className="page-gutter task-detail-main"><SectionTitle title={`${initials[stage]}课程`} action={`${stageCourses.length} 门课程`} />{stage === 'train' ? <div className="task-stage-groups">{(['follow','human','speech'] as const).map(type => { const list = stageCourses.filter(c => c.subtype === type); return list.length ? <section key={type}><h3>{type === 'follow' ? '跟读训练' : type === 'human' ? '人机训练' : '演讲训练'}</h3>{list.map(c => <TaskCourseRow key={c.id} course={c} go={go} />)}</section> : null; })}</div> : stageCourses.map(c => <TaskCourseRow key={c.id} course={c} go={go} />)}</main></Page>;
}
function TaskCourseRow({ course, go }: { course: Course; go: (route: string) => void }) { return <button className="task-course-row" onClick={() => go(`/course/${course.id}`)}><div className="task-row-cover"><img className="cover-back" src={course.cover} alt="" /><img className="cover-front" src={course.cover} alt="" /><span>{course.count} 个内容</span></div><div className="task-row-body"><div><strong>{course.title}</strong><span className={`status ${course.progress === 100 ? 'success' : course.progress ? 'blue' : ''}`}>{course.progress === 100 ? '已完成' : course.progress ? '进行中' : '待开始'}</span></div><div className="inline-progress"><Progress value={course.progress} /><b>{course.progress}%</b></div><footer><small>已完成 {Math.round(course.count * course.progress / 100)}/{course.count}</small><b>{course.progress === 100 ? '查看结果' : '开始课程'}<ChevronRight size={15} /></b></footer></div></button>; }

function CourseDetail({ course, go, back }: { course: Course; go: (route: string) => void; back: () => void }) {
  const [tab, setTab] = useState<'catalog'|'intro'|'review'>('catalog');
  const title = course.kind === 'learn' ? '学习课程详情' : course.kind === 'train' ? course.subtype === 'follow' ? '跟读训练详情' : '人机训练详情' : '考试课程详情';
  const action = () => go(course.kind === 'learn' ? `/content/${course.id}` : course.kind === 'train' ? `/training/${course.id}` : `/exam/rules/${course.id}`);
  return <Page go={go} className="detail-page with-action"><Topbar title={title} back={back} /><div className="course-detail-head"><div className="course-detail-cover"><img className="cover-back" src={course.cover} alt="" /><img className="cover-front" src={course.cover} alt="" /><span>{course.kind === 'learn' ? '自主学习课程' : course.kind === 'train' ? course.subtype === 'follow' ? '跟读练习' : '人机训练' : '考试测评'}</span></div><div className="course-detail-heading"><h1>{course.title}</h1><p>{course.summary}</p><div><span><Clock3 size={15} />{course.duration}</span><span><FileText size={15} />{course.count} {course.kind === 'exam' ? '道试题' : course.kind === 'train' ? '个内容' : '个课时'}</span></div></div></div>
    {course.kind === 'exam' ? <main className="page-gutter"><div className="info-card"><h2>考试概览</h2><div className="info-grid"><span><small>答题时长</small><b>30 分钟</b></span><span><small>题目数量</small><b>{course.count} 题</b></span><span><small>通过分数</small><b>80 分</b></span></div></div><div className="text-section"><h2>测评说明</h2><p>完成考试后即可查看成绩与答案解析。请先阅读考试规则，再开始答题。</p></div></main> : <><div className="detail-tabs">{([['catalog',course.kind === 'learn' ? '课程目录' : '训练内容'],['intro',course.kind === 'learn' ? '课程简介' : '训练评分'],['review','课程评价']] as const).map(([key,label]) => <button key={key} className={tab === key ? 'selected' : ''} onClick={() => setTab(key)}>{label}</button>)}</div><main className="page-gutter detail-tab-body">{tab === 'catalog' ? course.kind === 'learn' ? <div className="chapter-list">{['认识客户需求','建立服务对话','介绍合适方案','巩固与复盘'].slice(0, course.count).map((item,i) => <button key={item} onClick={() => go(`/content/${course.id}`)}><span className="chapter-icon"><Play size={18} fill="currentColor" /></span><span><strong>第 {i+1} 章 · {item}</strong><small>{i === 0 ? '视频 · 8 分钟' : i === 1 ? '文档 · 6 分钟' : '图文 · 5 分钟'}</small></span><ChevronRight size={18} /></button>)}</div> : course.subtype === 'follow' ? <FollowRounds /> : <div className="product-content"><ProductInfo /><DimensionCards /></div> : tab === 'intro' ? <div className="text-section"><h2>{course.kind === 'learn' ? '课程简介' : '训练评分'}</h2><p>{course.kind === 'learn' ? `${course.summary}。通过短视频、资料和练习，把知识用在真实岗位场景中。` : '训练结束后，将从需求确认、表达清晰、客户关怀和方案匹配等维度给出反馈。'}</p><div className="info-card"><h3>学习目标</h3><p>了解关键步骤，练习实际表达，并能独立完成一次完整的客户沟通。</p></div></div> : <Reviews course={course} />}</main></>}
    <FixedAction onClick={action}>{course.progress ? course.kind === 'exam' ? '查看规则并开始考试' : `继续${initials[course.kind]}` : courseAction[course.kind]}<ChevronRight size={18} /></FixedAction></Page>;
}
function ProductInfo() { const [product, setProduct] = useState(0); const [field, setField] = useState(0); const products = [
  { name: '家庭客户融合套餐', fields: ['帮助客户把宽带、手机流量和家庭共享权益组合在一起。', '一份账单管理全家通信，权益共享，更省心。', '客户担心费用高、办理复杂或权益使用不清楚。', '四口之家经常看视频、远程办公，可按使用人数和预算搭配权益。'] },
  { name: '5G 畅享套餐', fields: ['面向高频移动上网用户，提供充足流量和稳定体验。', '移动网络覆盖广，流量使用更从容。', '客户可能担心流量不够、网络不稳定或套餐变更繁琐。', '经常在外出差的客户，可以优先介绍流量与漫游权益。'] },
]; const labels = ['产品介绍','产品卖点','客户痛点','应用案例']; return <div className="info-card product-card"><div className="product-head"><h2>产品信息</h2><select aria-label="选择训练产品" value={product} onChange={e => { setProduct(Number(e.target.value)); setField(0); }}>{products.map((p,i) => <option key={p.name} value={i}>{p.name}</option>)}</select></div><strong>{products[product].name}</strong><div className="product-tabs">{labels.map((label,i) => <button key={label} className={field === i ? 'selected' : ''} onClick={() => setField(i)}>{label}</button>)}</div><p className="product-description">{products[product].fields[field]}</p></div>; }
function FollowRounds() { const [round, setRound] = useState(0); const items = [{ q: '您好，欢迎光临。请问有什么可以帮您？', a: '您好，我想了解一下适合全家使用的套餐。' }, { q: '请问家里平时有几个人一起使用网络？', a: '我们一家四口，平时会看视频和在线办公。' }, { q: '我先了解您的使用情况，再帮您推荐合适的方案。', a: '好的，请您介绍一下。' }]; const start = useRef(0); return <div className="follow-wrap"><div className="round-heading"><strong>练习轮次</strong><span>共 {items.length} 轮对话</span></div><div className="round-card" onTouchStart={e => start.current = e.touches[0].clientX} onTouchEnd={e => { const delta = e.changedTouches[0].clientX - start.current; if (Math.abs(delta) > 40) setRound(v => Math.min(items.length - 1, Math.max(0, v + (delta < 0 ? 1 : -1)))); }}><div className="round-card-top"><strong>第 {round+1} 轮 · 对话{round+1}</strong><b>{round+1}/{items.length}</b></div><div className="round-utterance question"><small>客户提问</small><p>{items[round].q}</p><Volume2 size={20} /></div><div className="round-utterance"><small>顾问回答</small><p>{items[round].a}</p><Volume2 size={20} /></div></div><div className="round-dots">{items.map((_,i) => <button key={i} className={round === i ? 'active' : ''} aria-label={`第${i+1}轮`} onClick={() => setRound(i)} />)}</div><p className="swipe-hint">左右滑动查看多轮对话</p></div>; }
function DimensionCards() { const [index, setIndex] = useState(0); const [flip, setFlip] = useState(false); const dims = [{ title: '需求确认', detail: '先询问使用人数和主要场景，再复述客户的真实需求。' }, { title: '表达清晰', detail: '用简洁的句子介绍权益，让客户听懂重点。' }, { title: '方案匹配', detail: '依据预算和场景推荐方案，并说明理由。' }]; return <section className="dimension-section"><SectionTitle title="评价维度" action={`${index+1}/${dims.length}`} /><button className={`dimension-card ${flip ? 'flipped' : ''}`} onClick={() => setFlip(!flip)}><span>{flip ? '维度说明' : '评价维度'}</span><strong>{flip ? dims[index].detail : dims[index].title}</strong><small>{flip ? '点击返回' : '点击翻面查看详情'}</small></button><div className="round-dots">{dims.map((_,i) => <button key={i} className={index === i ? 'active' : ''} onClick={() => { setIndex(i); setFlip(false); }} />)}</div></section>; }
function Reviews({ course }: { course: Course }) { return <div className="reviews"><div className="rating-summary"><b>4.8</b><div><div className="stars">★★★★★</div><small>来自 126 条课程评价</small></div></div><div className="review-item"><div><span className="mini-avatar">林</span><strong>林同学</strong><small>2 天前</small></div><div className="stars">★★★★★</div><p>内容清晰，和工作中的实际场景很贴近。</p></div><div className="review-item"><div><span className="mini-avatar">陈</span><strong>陈同学</strong><small>上周</small></div><div className="stars">★★★★★</div><p>学习节奏适中，练习后更知道如何回应客户了。</p></div><small className="muted">完成“{course.title}”后可在“我的 · 成长评价”中评分。</small></div>; }

function LearnContent({ course, go, back }: { course: Course; go: (route: string) => void; back: () => void }) { const [chapter, setChapter] = useState(0); const [complete, setComplete] = useState(false); const [playing, setPlaying] = useState(false); const titles = ['认识客户需求','建立服务对话','介绍合适方案','巩固与复盘']; return <Page go={go} className="detail-page with-action"><Topbar title="课程学习" back={back} action={<span className="topbar-meta">{chapter+1}/{course.count}</span>} /><div className="lesson-hero"><span>第 {chapter+1} 章</span><h1>{titles[chapter]}</h1><p>{course.title}</p></div><main className="page-gutter lesson-body"><button className="video-frame" onClick={() => setPlaying(!playing)}><img src={course.cover} alt="课程视频封面" /><span><Play fill="currentColor" size={25} /></span><small>{playing ? '播放中 · 演示预览' : '点击播放课程视频'}</small></button><div className="document-card"><div><FileText size={20} /><strong>学习资料</strong><span>文档预览</span></div><h2>新客接待与需求识别</h2><p>先用开放式问题了解客户的主要使用场景，再通过简短复述确认需求。表达方案时，围绕客户在意的重点说明价值。</p><p>在一次完整的客户沟通中，保持自然的服务语气，并在关键节点询问客户是否理解。</p></div><div className="lesson-next"><strong>课程目录</strong>{titles.slice(0, course.count).map((t,i) => <button key={t} className={chapter === i ? 'selected' : ''} onClick={() => { setChapter(i); setComplete(false); }}>0{i+1}　{t}<ChevronRight size={16} /></button>)}</div></main><FixedAction onClick={() => { if (chapter < course.count-1) { setChapter(chapter+1); setComplete(false); } else setComplete(true); }}>{complete ? <><Check size={18} /> 已完成学习</> : chapter === course.count-1 ? '完成学习' : '完成本章，学习下一章'}<ChevronRight size={18} /></FixedAction></Page>; }

function TrainingChat({ course, go, back }: { course: Course; go: (route: string) => void; back: () => void }) {
  const isFollow = course.subtype === 'follow';
  const [swapped, setSwapped] = useState(false); const [scene, setScene] = useState(false); const [textMode, setTextMode] = useState(false); const [input, setInput] = useState(''); const [hint, setHint] = useState(false); const [transcript, setTranscript] = useState<Record<number, boolean>>({});
  const [messages, setMessages] = useState<Message[]>([{ side: 'ai', text: isFollow ? '您好，欢迎光临。请问有什么可以帮您？' : '您好，您主要想了解哪方面的套餐？', time: now() }]);
  const count = messages.filter(m => m.side === 'me').length + 1; const bottom = useRef<HTMLDivElement>(null);
  useEffect(() => { bottom.current?.scrollIntoView({ behavior: 'smooth' }); }, [messages.length]);
  const playSpeech = (message: Message, index: number) => {
    if ('speechSynthesis' in window && 'SpeechSynthesisUtterance' in window) {
      window.speechSynthesis.cancel();
      const utterance = new SpeechSynthesisUtterance(message.text);
      utterance.lang = 'zh-CN';
      utterance.rate = 1;
      window.speechSynthesis.speak(utterance);
    } else setTranscript(state => ({ ...state, [index]: true }));
  };
  const send = () => { const clean = input.trim(); if (!clean) return; setMessages(prev => [...prev, { side: 'me', text: clean, time: now() }, { side: 'ai', text: isFollow ? '好的，我们再练习下一轮表达。您会怎样介绍这项服务？' : '我们一家四口，平时会看视频和在线办公。有什么合适的推荐吗？', time: now() }]); setInput(''); setHint(false); };
  return <Page go={go} className="chat-page"><Topbar title={isFollow ? '跟读训练' : '人机训练'} back={back} action={<button className="text-action" onClick={() => go(`/recap/${course.id}`)}>结束</button>} /><div className="chat-person"><div className="chat-person-round">第 {count} 轮</div><img src={asset(swapped ? 'role-b.png' : 'role-a.png')} alt="模拟客户头像" /><strong>{swapped ? '移动营业厅员工' : '客户顾问'}</strong><div className="chat-person-actions"><button onClick={() => setSwapped(!swapped)}>切换角色</button></div></div><div className="chat-scene"><span>{course.title}</span><button onClick={() => setScene(!scene)}>训练场景<ChevronDown size={16} /></button></div>{scene && <div className="scene-panel"><strong>家庭融合套餐咨询</strong><p>AI 与学员分别扮演客户和营业厅员工。切换角色后，双方在对话中的方向会互换。</p></div>}
    <div className="chat-feed"><span className="time-divider">{now()}</span>{messages.map((m,i) => { const visualSide = m.side === 'ai' ? (swapped ? 'me' : 'ai') : (swapped ? 'ai' : 'me'); return <div className={`chat-message ${visualSide}`} key={i}><img src={asset(m.side === 'ai' ? swapped ? 'role-b.png' : 'role-a.png' : swapped ? 'role-a.png' : 'role-b.png')} alt="" /><div className="bubble-wrap"><div className="bubble">{m.side === 'ai' && !transcript[i] ? <><button className="voice-play" onClick={() => playSpeech(m, i)}><Play size={15} fill="currentColor" /><span className="wave">▂▅▃▇▅▂▄▆▃▅▂</span><small>00:08</small></button><button className="transcript-button" onClick={() => setTranscript(s => ({ ...s, [i]: true }))}>转文字</button></> : m.text}</div>{m.side === 'ai' && visualSide === 'ai' && <button className="speech-hint" onClick={() => setHint(!hint)}><Lightbulb size={17} />话术提示<ChevronRight size={15} /></button>}{m.side === 'ai' && visualSide === 'ai' && hint && i === messages.length - 1 && <div className="hint-card">先确认家庭使用人数，再介绍适合的套餐权益。</div>}</div></div>; })}<div ref={bottom} /></div>
    <div className="chat-composer"><button className="icon-button" aria-label="切换输入方式" onClick={() => setTextMode(!textMode)}>{textMode ? <Mic size={21} /> : <MoreHorizontal size={23} />}</button>{textMode ? <input value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && send()} placeholder="输入你的回答…" /> : <button className="hold-to-talk" onClick={() => { setInput('我想了解适合家庭使用的套餐。'); setTextMode(true); }}>按住说话 <small>点击模拟语音输入</small></button>}<button className="composer-send" onClick={send} disabled={!input.trim()} aria-label="发送"><Send size={19} /></button></div></Page>;
}

function TrainingRecap({ course, go, back }: { course: Course; go: (route: string) => void; back: () => void }) { const [tab, setTab] = useState<'report'|'speech'|'tip'>('report'); return <Page go={go} className="detail-page with-action recap-page"><Topbar title="训练复盘" back={back} /><div className="recap-hero"><div><h1>{course.title}</h1><p>今天 {now()} · 语音训练</p></div><div><b>86</b><small>/100</small><span>已通过</span></div></div><div className="detail-tabs"><button className={tab === 'report' ? 'selected' : ''} onClick={() => setTab('report')}>分析报告</button><button className={tab === 'speech' ? 'selected' : ''} onClick={() => setTab('speech')}>话术复盘</button><button className={tab === 'tip' ? 'selected' : ''} onClick={() => setTab('tip')}>沟通秘籍</button></div><main className="page-gutter recap-main">{tab === 'report' ? <><SectionTitle title="AI 训练总评" /><p className="summary-note">整体表现稳定，可以继续打磨关键场景下的表达细节。</p><div className="recap-stats"><span><b>1</b><small>待提升项</small></span><span><b>2</b><small>优势项</small></span><span><b>6</b><small>训练分钟</small></span></div><SectionTitle title="待提升项" /><div className="feedback-card"><strong>需求确认 <em>基本达标</em></strong><p>提问后还可以多复述一次客户的核心需求。</p></div><SectionTitle title="优势项" /><div className="feedback-card positive"><strong>表达清晰 <em>92/100</em></strong><p>介绍方案时结构清楚，重点表达准确。</p></div><SectionTitle title="下一轮提升路径" /><div className="step-card"><span>1</span><div><strong>需求确认</strong><p>使用开放式问题，再用一句话确认客户目标。</p></div></div></> : tab === 'speech' ? <><SectionTitle title="对话回顾" /><div className="feedback-card"><strong>客户</strong><p>您主要想了解哪方面的套餐？</p></div><div className="feedback-card positive"><strong>我的回答</strong><p>我先了解一下您家里的使用情况，再推荐合适的方案。</p></div><div className="feedback-card"><strong>AI 建议</strong><p>可以补充询问预算范围，让后续推荐更准确。</p></div></> : <><SectionTitle title="沟通秘籍" /><div className="feedback-card"><strong>先问，再推荐</strong><p>通过使用人数、上网习惯和预算三个问题建立需求画像。</p></div><div className="feedback-card positive"><strong>说清价值</strong><p>把套餐权益和客户的具体使用场景一一对应。</p></div></>}</main><FixedAction onClick={() => go(`/training/${course.id}`)}>重新训练<RotateCcw size={17} /></FixedAction></Page>; }

function ExamRules({ course, go, back }: { course: Course; go: (route: string) => void; back: () => void }) { return <Page go={go} className="detail-page with-action"><Topbar title="考试规则" back={back} /><div className="light-hero"><span className="eyebrow">考试课程 · 开始前请阅读</span><h1>{course.title}</h1><p>了解答题时间、题量与通过要求，准备好后即可开始。</p></div><main className="page-gutter rules-body"><div className="info-card"><h2>考试概览</h2><div className="rule-grid">{[['考试次数','3 次'],['剩余次数','2 次'],['考试总分','100 分'],['通过分数','80 分'],['考试题数','5 题'],['答题时长','30 分钟']].map(([a,b]) => <div key={a}><small>{a}</small><strong>{b}</strong></div>)}</div></div><div className="info-card"><h2>题型分布</h2>{questions.map(q => <div className="rule-line" key={q.type}><span>{q.type}</span><strong>1 题 · 共 20 分</strong></div>)}</div></main><FixedAction onClick={() => go(`/exam/quiz/${course.id}`)}>开始考试<ChevronRight size={18} /></FixedAction></Page>; }
function ExamQuiz({ course, go, back }: { course: Course; go: (route: string) => void; back: () => void }) { const [index, setIndex] = useState(0); const [answers, setAnswers] = useState<Record<number,string[]>>({}); const [sheet, setSheet] = useState(false); const [confirmSubmit, setConfirmSubmit] = useState(false); const q = questions[index]; const selected = answers[index] || []; const done = Object.values(answers).filter(a => a.length && a.some(Boolean)).length; const choose = (value: string) => setAnswers(prev => ({ ...prev, [index]: q.type === '多选题' ? selected.includes(value) ? selected.filter(v => v !== value) : [...selected,value] : [value] })); const submit = () => { const correct = questions.filter((item,i) => { const picked = answers[i] || []; return picked.length === item.answer.length && picked.every(value => item.answer.includes(value)); }).length; go(`/exam/result/${course.id}?score=${correct*20}`); }; return <Page go={go} className="detail-page with-action quiz-page"><Topbar title={course.title} back={back} /><div className="quiz-progress"><div><span>答题进度 <b>{done}</b>/{questions.length}</span><span>剩余时间 <b>29:51</b></span></div><small>当前第 {index+1} 题，已完成 {Math.round(done / questions.length * 100)}%</small><Progress value={done / questions.length * 100} /></div><main className="page-gutter"><div className="quiz-card"><div className="quiz-card-top"><strong>第 {index+1} / {questions.length} 题</strong><button onClick={() => setSheet(true)}>查看答题卡 <ChevronRight size={15} /></button></div><div className="question-body"><span className="question-type">{q.type} · 20 分</span><h1>{q.title}</h1><p>{q.type === '多选题' ? '请选择所有符合的答案' : q.options ? '请选择一个答案' : '请填写你的答案'}</p>{q.options ? <div className="answer-options">{q.options.map((item,i) => { const key = String.fromCharCode(65+i); return <button key={key} className={selected.includes(key) ? 'selected' : ''} onClick={() => choose(key)}><span>{key}</span><strong>{item}</strong><i>{selected.includes(key) && <Check size={15} />}</i></button>; })}</div> : <textarea rows={q.type === '问答题' ? 5 : 2} placeholder={q.type === '填空题' ? '输入填空答案' : '写下你的回答'} value={selected[0] || ''} onChange={e => setAnswers(prev => ({ ...prev, [index]: [e.target.value] }))} />}</div></div></main><footer className="quiz-footer"><button onClick={() => setIndex(Math.max(0,index-1))} disabled={index === 0}>上一题</button><button className="primary-button" onClick={() => index === questions.length-1 ? setConfirmSubmit(true) : setIndex(index+1)}>{index === questions.length-1 ? '提交试卷' : '下一题'}</button></footer>{sheet && <div className="modal-shade" onClick={() => setSheet(false)}><div className="sheet" onClick={e => e.stopPropagation()}><div className="sheet-head"><strong>答题卡</strong><button onClick={() => setSheet(false)}><X size={20} /></button></div><p>已完成 {done}/{questions.length} 题</p><div className="answer-grid">{questions.map((_,i) => <button key={i} className={`${i === index ? 'current' : ''} ${answers[i]?.length ? 'done' : ''}`} onClick={() => { setIndex(i); setSheet(false); }}>{i+1}</button>)}</div></div></div>}{confirmSubmit && <div className="modal-shade" onClick={() => setConfirmSubmit(false)}><div className="sheet submit-sheet" onClick={e => e.stopPropagation()}><div className="sheet-head"><strong>确认提交试卷</strong><button onClick={() => setConfirmSubmit(false)}><X size={20} /></button></div><p>{done === questions.length ? '全部题目已作答，提交后可查看成绩。' : `还有 ${questions.length-done} 道题未作答，确定提交吗？`}</p><div><button onClick={() => setConfirmSubmit(false)}>继续答题</button><button className="primary-button" onClick={submit}>确认提交</button></div></div></div>}</Page>; }
function ExamResult({ course, score, go, back }: { course: Course; score: number; go: (route: string) => void; back: () => void }) { const [show, setShow] = useState(false); const passed = score >= 80; return <Page go={go} className="detail-page with-action"><Topbar title="考试成绩" back={back} /><div className={`result-hero ${passed ? '' : 'failed'}`}><CheckCircle2 size={42} /><span>本次测评已完成</span><b>{score}<small>分</small></b><p>{passed ? '达到通过要求 · 继续保持' : '距离通过还差一点 · 复习后再试'}</p></div><main className="page-gutter"><div className="info-card"><h2>成绩概览</h2><div className="info-grid"><span><small>答对题目</small><b>{score/20} / 5</b></span><span><small>通过分数</small><b>80 分</b></span><span><small>用时</small><b>12 分钟</b></span></div></div><SectionTitle title="答案解析" action={show ? '收起' : '查看全部'} onAction={() => setShow(!show)} />{show && questions.map((q,i) => <div className="analysis-row" key={i}><strong>{i+1}. {q.title}</strong><p>参考答案：{q.answer.join('、')}</p></div>)}</main><FixedAction onClick={() => go('/courses')}>返回课程中心<ArrowRight size={18} /></FixedAction></Page>; }

type ChatSession = { id: string; title: string; time: string };
function chatSessions(appId?: string): ChatSession[] {
  const prefix = `chat-${appId || 'terminal'}-`;
  return Object.keys(localStorage).filter(key => key.startsWith(prefix)).map(key => {
    const data = readStore<Message[]>(key, []);
    const first = data.find(item => item.side === 'me');
    return { id: key.slice(prefix.length), title: first?.text || '新对话', time: data[data.length - 1]?.time || '' };
  }).sort((a, b) => Number(b.id) - Number(a.id));
}
function chatIntent(text: string): 'task' | 'course' | 'knowledge' {
  if (/任务|待办|截止|完成/.test(text)) return 'task';
  if (/课程|学习|训练|考试|练习/.test(text)) return 'course';
  return 'knowledge';
}
function WhaleHome({ go }: { go: (route: string) => void }) {
  const [input, setInput] = useState('');
  const [page, setPage] = useState(0);
  const [historyOpen, setHistoryOpen] = useState(false);
  const entry = (text: string) => {
    if (!text.trim()) return;
    const id = String(Date.now());
    sessionStorage.setItem(`whale-prompt-${id}`, text.trim());
    go(`/whale/chat?session=${id}`);
  };
  return <Page tab="whale" go={go} className="whale-page">
    <div className="whale-hero"><span className="eyebrow">你的学习与工作助手</span><button onClick={() => setHistoryOpen(true)}>对话记录<ChevronRight size={15} /></button><h1>鲸小智</h1><p>一句话找任务、课程和知识</p><img src={asset('whale-hero.webp')} alt="" /></div>
    <main className="page-gutter">
      <div className="whale-entry"><strong><Sparkles size={17} />告诉我你的需求</strong><textarea rows={2} value={input} onChange={e => setInput(e.target.value)} placeholder="告诉我你想完成什么…" onKeyDown={e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); entry(input); } }} /><div><button onClick={() => setInput('我有哪些任务没完成？')}><Mic size={17} />语音提问示例</button><button className="primary-button" disabled={!input.trim()} onClick={() => entry(input)}><Send size={16} />发送</button></div></div>
      <SectionTitle title="精选训练" action="更多训练" onAction={() => go('/courses')} /><button className="whale-training" onClick={() => go('/course/train-1')}><img src={asset('course-communication.webp')} alt="" /><span><strong>新客接待模拟训练</strong><small>查看训练<ChevronRight size={15} /></small></span></button>
      <SectionTitle title="知识应用" action="左右滑动查看更多" /><div className="apps-track" onScroll={e => setPage(Math.round(e.currentTarget.scrollLeft / e.currentTarget.clientWidth))}><div className="apps-slide">{apps.slice(0,4).map((app,i) => <button className={`app-card ${app.color}`} key={app.id} onClick={() => go(`/whale/app/${app.id}?session=${Date.now()}`)}><span className="app-icon">{i % 2 ? <FileText /> : <MessageCircle />}</span><strong>{app.name}</strong><small>{app.desc}</small></button>)}</div><div className="apps-slide">{apps.slice(4).map((app,i) => <button className={`app-card ${app.color}`} key={app.id} onClick={() => go(`/whale/app/${app.id}?session=${Date.now()}`)}><span className="app-icon">{i % 2 ? <FileText /> : <MessageCircle />}</span><strong>{app.name}</strong><small>{app.desc}</small></button>)}</div></div><div className="carousel-dots normal"><i className={page === 0 ? 'active' : ''} /><i className={page === 1 ? 'active' : ''} /></div>
    </main>
    {historyOpen && <div className="modal-shade" onClick={() => setHistoryOpen(false)}><div className="sheet" onClick={e => e.stopPropagation()}><div className="sheet-head"><strong>鲸小智对话记录</strong><button onClick={() => setHistoryOpen(false)}><X size={19} /></button></div>{chatSessions().length ? chatSessions().map(session => <button className="history-session" key={session.id} onClick={() => go(`/whale/chat?session=${session.id}`)}>{session.title}<small>{session.time} · 点击继续对话</small></button>) : <p className="sheet-empty">还没有对话记录，输入问题即可开始。</p>}</div></div>}
  </Page>;
}
function WhaleChat({ go, back, appId, sessionId }: { go: (route: string) => void; back: () => void; appId?: string; sessionId: string }) {
  const app = apps.find(a => a.id === appId);
  const storageKey = `chat-${appId || 'terminal'}-${sessionId}`;
  const prompt = app ? '' : sessionStorage.getItem(`whale-prompt-${sessionId}`) || '';
  const initial: Message[] = prompt ? [
    { side: 'me', text: prompt, time: now() },
    { side: 'ai', text: chatIntent(prompt) === 'task' ? '我找到了待完成的任务，点开就能继续。' : chatIntent(prompt) === 'course' ? '我找到了与你需求相关的课程和训练。' : '这类问题适合在知识应用中检索，你可以选择下方应用继续提问。', time: now() },
  ] : [];
  const [messages, setMessages] = useState<Message[]>(() => readStore(storageKey, initial));
  const [input, setInput] = useState('');
  const [switcher, setSwitcher] = useState(false);
  const [historyOpen, setHistoryOpen] = useState(false);
  const bottom = useRef<HTMLDivElement>(null);
  useEffect(() => { if (messages.length) localStorage.setItem(storageKey, JSON.stringify(messages)); }, [messages, storageKey]);
  useEffect(() => { bottom.current?.scrollIntoView({ block: 'end' }); }, [messages.length]);
  const send = () => {
    const clean = input.trim(); if (!clean) return;
    const intent = chatIntent(clean);
    const answer = app ? `我查阅了${app.name}的模拟知识内容。针对“${clean}”，建议先确认具体场景，再用清晰的步骤回应；也可以继续补充客户情况，我会细化回答。` : intent === 'task' ? '我找到了待完成的任务，点开就能继续。' : intent === 'course' ? '我找到了与你需求相关的课程和训练。' : '这类问题适合在知识应用中检索，你可以选择下方应用继续提问。';
    setMessages(prev => [...prev, { side: 'me', text: clean, time: now() }, { side: 'ai', text: answer, time: now() }]);
    setInput('');
  };
  const newSession = () => go(`/whale/${appId ? `app/${appId}` : 'chat'}?session=${Date.now()}`);
  const openSession = (id: string) => go(`/whale/${appId ? `app/${appId}` : 'chat'}?session=${id}`);
  return <Page go={go} className="chat-page whale-chat">
    <Topbar title={app?.name || '鲸小智'} back={back} action={<div className="topbar-actions">{app && <button aria-label="切换知识应用" onClick={() => setSwitcher(true)}>切换</button>}<button aria-label="查看历史对话" onClick={() => setHistoryOpen(true)}><ListChecks size={19} /></button></div>} />
    <div className="whale-chat-feed">{messages.length ? messages.map((m,i) => {
      const previous = messages[i-1];
      const intent = m.side === 'ai' && !app && previous?.side === 'me' ? chatIntent(previous.text) : null;
      return <div className={`knowledge-message ${m.side}`} key={i}><span className="time-divider">{m.time}</span><div className="knowledge-row"><span className="knowledge-avatar">{m.side === 'me' ? '我' : '智'}</span><div className="knowledge-bubble">{m.text}</div></div>{intent && <div className="result-list"><span>{intent === 'knowledge' ? '推荐使用知识应用' : '为你找到以下结果'}</span>{intent === 'task' ? <><button onClick={() => go('/task/task-1')}><span className="result-icon"><ListChecks size={20} /></span><span><strong>新员工岗位能力提升任务</strong><small>还有 2 门课程待完成</small></span><ChevronRight size={17} /></button><button onClick={() => go('/task/task-2')}><span className="result-icon"><ListChecks size={20} /></span><span><strong>家庭宽带营销任务</strong><small>5 天后到期</small></span><ChevronRight size={17} /></button></> : intent === 'course' ? <><button onClick={() => go('/course/train-1')}><span className="result-icon"><BookOpen size={20} /></span><span><strong>新客接待模拟训练</strong><small>12 分钟 · 人机训练</small></span><ChevronRight size={17} /></button><button onClick={() => go('/course/learn-1')}><span className="result-icon"><BookOpen size={20} /></span><span><strong>新客接待与需求识别</strong><small>20 分钟 · 学习课程</small></span><ChevronRight size={17} /></button></> : apps.slice(0,3).map(item => <button key={item.id} onClick={() => go(`/whale/app/${item.id}?session=${Date.now()}`)}><span className="result-icon"><MessageCircle size={20} /></span><span><strong>{item.name}</strong><small>{item.desc}</small></span><ChevronRight size={17} /></button>)}</div>}</div>;
    }) : <div className="chat-start"><Sparkles size={28} /><strong>有什么想了解的？</strong><p>{app ? `向${app.name}提问，快速找到知识答案。` : '找任务、课程和知识，都可以问我。'}</p></div>}<div ref={bottom} /></div>
    <div className="chat-composer"><button className="icon-button" onClick={() => setInput('我有哪些任务没完成？')} aria-label="语音提问示例"><Mic size={20} /></button><input value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && send()} placeholder={app ? `向${app.name}提问…` : '问问鲸小智…'} /><button className="composer-send" onClick={send} disabled={!input.trim()} aria-label="发送"><Send size={19} /></button></div>
    {(switcher || historyOpen) && <div className="modal-shade" onClick={() => { setSwitcher(false); setHistoryOpen(false); }}><div className="sheet" onClick={e => e.stopPropagation()}><div className="sheet-head"><strong>{switcher ? '切换知识应用' : '历史对话'}</strong><button onClick={() => { setSwitcher(false); setHistoryOpen(false); }}><X size={20} /></button></div>{switcher ? apps.map(a => <button className="sheet-row" key={a.id} onClick={() => go(`/whale/app/${a.id}?session=${Date.now()}`)}>{a.name}<ChevronRight size={17} /></button>) : <><button className="sheet-row" onClick={newSession}>新建对话<ChevronRight size={17} /></button>{chatSessions(appId).map(session => <button className="history-session" key={session.id} onClick={() => openSession(session.id)}>{session.title}<small>{session.time} · 点击继续对话</small></button>)}{!chatSessions(appId).length && <p className="sheet-empty">暂无历史对话</p>}</>}</div></div>}
  </Page>;
}

function MyPage({ go }: { go: (route: string) => void }) { return <Page tab="my" go={go} className="my-page"><div className="my-hero"><div className="my-person"><img src={asset('default-avatar.png')} alt="" /><div><strong>演示学员</strong><small>技术部 · 坚持成长的第 28 天</small></div></div><div className="my-progress"><div><span>本月成长进度</span><b>68%</b></div><Progress value={68} /><p>再完成 2 项任务，解锁下一阶段能力评价</p></div></div><main className="page-gutter"><div className="my-stat-line"><button onClick={() => go('/my/courses')}><b>{courses.filter(c => c.progress === 100).length}</b><span>已完成课程</span></button><button onClick={() => go('/my/tasks')}><b>{tasks.filter(t => t.status !== '已完成').length}</b><span>待完成任务</span></button><button onClick={() => go('/my/history')}><b>24</b><span>累计训练次数</span></button></div><SectionTitle title="我的成长" /><div className="my-entry-list"><button onClick={() => go('/my/rank')}><span className="my-entry-icon blue"><Trophy size={21} /></span><span><strong>排行榜</strong><small>看看本月的成长排名</small></span><ChevronRight /></button><button onClick={() => go('/my/growth')}><span className="my-entry-icon green"><Star size={21} /></span><span><strong>成长评价</strong><small>训练能力与课程评价</small></span><ChevronRight /></button><button onClick={() => go('/my/history')}><span className="my-entry-icon violet"><Clock3 size={21} /></span><span><strong>训练历史</strong><small>查看练习记录与复盘</small></span><ChevronRight /></button></div><SectionTitle title="学习概览" /><div className="my-overview"><button onClick={() => go('/my/courses')}><BookOpen size={20} /><strong>课程详情</strong><span>已完成 {courses.filter(c => c.progress === 100).length} 门<ChevronRight size={16} /></span></button><button onClick={() => go('/my/tasks')}><ListChecks size={20} /><strong>任务完成情况</strong><span>已完成 {tasks.filter(t => t.status === '已完成').length} 项<ChevronRight size={16} /></span></button></div></main></Page>; }
function RankPage({ go, back }: { go: (route: string) => void; back: () => void }) {
  const [type, setType] = useState('人机训练');
  const [sort, setSort] = useState('勤奋榜');
  const [org, setOrg] = useState('全部组织');
  const [month, setMonth] = useState('2026年10月');
  const [sheet, setSheet] = useState<'说明'|'组织'|'月份'|null>(null);
  const groupFor = (team: string) => ['市场部','销售部'].includes(team) ? '营销与销售组' : ['产品部','运营部'].includes(team) ? '产品与运营组' : '管理与支持组';
  const orgOptions = ['全部组织','营销与销售组','产品与运营组','管理与支持组'];
  const baseValues: Record<string, number[]> = { '人机训练':[24,20,18,16,14,12], '跟读训练':[22,19,17,15,13,11], '演讲训练':[19,18,16,14,12,10], '学习':[15,14,12,11,9,8], '考试':[12,11,10,9,8,7] };
  const monthOffset = month === '2026年10月' ? 0 : month === '2026年9月' ? -2 : -4;
  const rankedAll = people.map((person,index) => ({ ...person, score: (sort === '优秀榜' ? [98,95,92,89,86,83][index] : baseValues[type][index]) + monthOffset })).sort((a,b) => b.score-a.score);
  const ranked = rankedAll.filter(person => org === '全部组织' || groupFor(person.team) === org);
  const podium = ranked.length >= 3 ? [ranked[1],ranked[0],ranked[2]] : [];
  const userRank = rankedAll.findIndex(person => person.name === '演示学员') + 1;
  const userScore = rankedAll.find(person => person.name === '演示学员')?.score || 0;
  const scoreLabel = sort === '优秀榜' ? '综合得分' : type === '学习' ? '已学课程' : type === '考试' ? '考试次数' : `${type}次数`;
  const scoreUnit = sort === '优秀榜' ? '分' : type === '学习' ? '门' : '次';
  return <Page go={go} className="detail-page rank-page">
    <Topbar title="排行榜" back={back} action={<button className="text-action" onClick={() => setSheet('说明')}>榜单说明</button>} />
    <div className="rank-subtitle">以训练见成长 · 用数据看进步</div>
    <div className="rank-types">{['人机训练','跟读训练','演讲训练','学习','考试'].map(item => <button key={item} className={type === item ? 'selected' : ''} onClick={() => setType(item)}>{item}</button>)}</div>
    <div className="rank-filters"><button onClick={() => setSheet('组织')}><Users size={18} />{org}<ChevronDown size={17} /></button><button onClick={() => setSheet('月份')}><CalendarDays size={18} />{month}<ChevronDown size={17} /></button></div>
    <div className="rank-toggle"><button className={sort === '勤奋榜' ? 'selected' : ''} onClick={() => setSort('勤奋榜')}><strong>勤奋榜</strong><small>{scoreLabel}排名</small></button><button className={sort === '优秀榜' ? 'selected' : ''} onClick={() => setSort('优秀榜')}><strong>优秀榜</strong><small>综合表现排名</small></button></div>
    {podium.length ? <div className="rank-podium">{podium.map((p,i) => <div key={p.name} className={`podium-place place-${i}`}><span className="crown">♛</span><img src={p.avatar} alt="" /><strong>{p.name}</strong><small>{p.team}</small><b>{p.score}<em> {scoreUnit}</em></b><span>{scoreLabel}</span></div>)}</div> : <div className="rank-empty">该组织共有 {ranked.length} 人上榜，名单见下方。</div>}
    <button className="my-rank" onClick={() => go('/my/history')}><span>我的排名</span><b>第 <strong>{userRank}</strong> 名</b><img src={people[3].avatar} alt="" /><div><strong>演示学员</strong><small>技术部 · 全组织</small></div><b>{userScore} {scoreUnit}</b><ChevronRight size={18} /></button>
    <div className="rank-list">{ranked.length >= 3 ? ranked.slice(3).map((p,i) => <div key={p.name}><b>{i+4}</b><img src={p.avatar} alt="" /><span><strong>{p.name}</strong><small>{p.team}</small></span><b>{p.score} {scoreUnit}</b></div>) : ranked.map((p,i) => <div key={p.name}><b>{i+1}</b><img src={p.avatar} alt="" /><span><strong>{p.name}</strong><small>{p.team}</small></span><b>{p.score} {scoreUnit}</b></div>)}</div>
    {sheet && <div className="modal-shade" onClick={() => setSheet(null)}><div className="sheet" onClick={e => e.stopPropagation()}><div className="sheet-head"><strong>{sheet === '说明' ? '榜单说明' : `选择${sheet}`}</strong><button onClick={() => setSheet(null)}><X size={20} /></button></div>{sheet === '说明' ? <p className="sheet-copy">勤奋榜按所选类别统计参与次数，优秀榜按综合表现评分。切换组织与月份后，榜单会同步更新。此处为本地演示数据。</p> : (sheet === '组织' ? orgOptions : ['2026年10月','2026年9月','2026年8月']).map(item => <button className="sheet-row" key={item} onClick={() => { sheet === '组织' ? setOrg(item) : setMonth(item); setSheet(null); }}>{item}<ChevronRight size={17} /></button>)}</div></div>}
  </Page>;
}
function GrowthPage({ go, back }: { go: (route: string) => void; back: () => void }) { const [tab, setTab] = useState<'ability'|'reviews'>('ability'); const [rating, setRating] = useState<Record<string,number>>(() => readStore('course-ratings', {})); useEffect(() => { localStorage.setItem('course-ratings', JSON.stringify(rating)); }, [rating]); const [selected, setSelected] = useState<Course|null>(null); const [ratingDraft, setRatingDraft] = useState(0); return <Page go={go} className="detail-page"><Topbar title="成长评价" back={back} /><div className="light-hero"><span className="eyebrow">能力与课程的成长记录</span><h1>每一次学习都有回响</h1><p>从训练反馈到课程评价，了解自己的进步。</p></div><div className="detail-tabs"><button className={tab === 'ability' ? 'selected' : ''} onClick={() => setTab('ability')}>训练综合评价</button><button className={tab === 'reviews' ? 'selected' : ''} onClick={() => setTab('reviews')}>课程评价</button></div><main className="page-gutter">{tab === 'ability' ? <><div className="ability-score"><span>综合能力得分</span><strong>86<small>/100</small></strong><p>相比上月提升 8 分</p></div><SectionTitle title="能力维度" />{[['表达清晰',92],['需求确认',68],['方案匹配',84],['客户关怀',88]].map(([label,value]) => <div className="ability-row" key={label}><span>{label}</span><Progress value={Number(value)} /><b>{value}</b></div>)}<div className="feedback-card"><strong>本月建议</strong><p>重点练习需求确认，在推荐方案前多问一个问题。</p></div></> : <><SectionTitle title="已完成课程" />{courses.filter(c => c.progress === 100).map(c => <div className="rating-row" key={c.id}><img src={c.cover} alt="" /><div><strong>{c.title}</strong><small>{initials[c.kind]}课程 · {rating[c.id] ? `${rating[c.id]} 星 · 已评分` : '尚未评分'}</small></div><button onClick={() => { setSelected(c); setRatingDraft(rating[c.id] || 0); }}>{rating[c.id] ? '修改评分' : '去评分'}<ChevronRight size={15} /></button></div>)}</>}</main>{selected && <div className="modal-shade" onClick={() => setSelected(null)}><div className="sheet rating-sheet" onClick={e => e.stopPropagation()}><div className="sheet-head"><strong>评价课程</strong><button onClick={() => setSelected(null)}><X size={20} /></button></div><p>{selected.title}</p><div className="rating-stars">{[1,2,3,4,5].map(value => <button key={value} onClick={() => setRatingDraft(value)} className={ratingDraft >= value ? 'selected' : ''}>★</button>)}</div><button className="primary-button" onClick={() => { setRating(r => ({ ...r, [selected.id]: ratingDraft })); setSelected(null); }} disabled={!ratingDraft}>保存评分</button></div></div>}</Page>; }
function HistoryPage({ go, back }: { go: (route: string) => void; back: () => void }) {
  const [type, setType] = useState('人机训练');
  const [category, setCategory] = useState('全部');
  const [date, setDate] = useState('全部日期');
  const [dateOpen, setDateOpen] = useState(false);
  const typeCourses = type === '人机训练' ? courses.filter(c => c.subtype === 'human') : type === '跟读训练' ? courses.filter(c => c.subtype === 'follow') : type === '演讲训练' ? courses.filter(c => c.subtype === 'speech') : courses.filter(c => c.subtype === 'human' && c.category === '客户服务');
  const visible = typeCourses.filter(c => (category === '全部' || c.category === category) && (date !== '今天' || typeCourses.indexOf(c) === 0));
  return <Page go={go} className="detail-page"><Topbar title="训练历史" back={back} /><div className="history-intro">回顾练习与评价结果</div><div className="history-tabs">{['人机训练','跟读训练','演讲训练','客户答疑'].map(t => <button key={t} className={type === t ? 'selected' : ''} onClick={() => { setType(t); setCategory('全部'); }}>{t}</button>)}</div><main className="page-gutter"><div className="history-filter"><div><strong>训练场景</strong><button onClick={() => setDateOpen(true)}><CalendarDays size={15} />{date}</button></div><div>{['全部','营销拓展','客户服务','业务办理'].map(c => <button key={c} className={category === c ? 'selected' : ''} onClick={() => setCategory(c)}>{c}</button>)}</div></div><SectionTitle title="训练记录" action="重置筛选" onAction={() => { setCategory('全部'); setDate('全部日期'); }} />{visible.length ? visible.map((c,i) => <button className="history-row" key={c.id} onClick={() => go(`/recap/${c.id}`)}><span className="history-icon"><Clock3 size={21} /></span><span><strong>{c.title}</strong><small>{i === 0 ? '客户咨询家庭套餐' : '客户关心办理条件'}</small><small>{i === 0 ? '今天 10:20' : '昨天 16:30'}</small></span><b>{[86,81,90][i % 3]} 分</b><ChevronRight size={16} /></button>) : <Empty title="暂无训练记录" hint="调整场景或日期后再看看" action="清空筛选" onAction={() => { setCategory('全部'); setDate('全部日期'); }} />}<p className="end-list">已展示全部记录</p></main>{dateOpen && <div className="modal-shade" onClick={() => setDateOpen(false)}><div className="sheet" onClick={e => e.stopPropagation()}><div className="sheet-head"><strong>选择日期</strong><button onClick={() => setDateOpen(false)}><X size={20} /></button></div>{['全部日期','今天','最近一周'].map(item => <button key={item} className="sheet-row" onClick={() => { setDate(item); setDateOpen(false); }}>{item}<ChevronRight size={17} /></button>)}</div></div>}</Page>;
}
function StatsPage({ mode, go, back }: { mode: 'courses'|'tasks'; go: (route: string) => void; back: () => void }) {
  const done = mode === 'courses' ? courses.filter(c => c.progress === 100).length : tasks.filter(t => t.status === '已完成').length;
  const total = mode === 'courses' ? courses.length : tasks.length;
  return <Page go={go} className="detail-page"><Topbar title={mode === 'courses' ? '课程详情' : '任务完成情况'} back={back} /><div className="light-hero"><span className="eyebrow">我的 · 学习记录</span><h1>{mode === 'courses' ? '课程学习详情' : '任务执行进度'}</h1><p>{mode === 'courses' ? '学、训、考课程的整体学习情况' : '查看管理员指派任务的完成情况'}</p></div><main className="page-gutter"><div className="stats-strip"><span><b>{done}</b><small>已完成</small></span><span><b>{total-done}</b><small>待完成</small></span><span><b>{Math.round(done/total*100)}%</b><small>完成率</small></span></div><SectionTitle title={mode === 'courses' ? '课程详情统计' : '任务列表'} />{mode === 'courses' ? <>{(['learn','train','exam'] as const).map(kind => { const list = courses.filter(c => c.kind === kind); const complete = list.filter(c => c.progress === 100).length; return <div className="ability-row" key={kind}><span>{initials[kind]}课程</span><Progress value={complete/list.length*100} /><b>{complete}/{list.length}</b></div>; })}<button className="subtle-link" onClick={() => go('/courses')}>前往课程中心查看课程<ChevronRight size={16} /></button></> : tasks.map(t => <TaskCard key={t.id} task={t} go={go} />)}</main></Page>;
}
function SearchPage({ go, back }: { go: (route: string) => void; back: () => void }) { const [query, setQuery] = useState(''); const list = courses.filter(c => c.title.includes(query) || c.category.includes(query)); return <Page go={go} className="detail-page"><Topbar title="搜索课程" back={back} /><main className="page-gutter"><div className="search-line search-page-input"><Search size={19} /><input autoFocus value={query} onChange={e => setQuery(e.target.value)} placeholder="输入课程名称或关键词" />{query && <button onClick={() => setQuery('')}><X size={17} /></button>}</div><SectionTitle title={query ? `找到 ${list.length} 门课程` : '推荐课程'} /><div className="course-grid">{(query ? list : courses.slice(0,4)).map(c => <CourseCard key={c.id} course={c} onClick={() => go(`/course/${c.id}`)} />)}</div></main></Page>; }
function MessagesPage({ go, back }: { go: (route: string) => void; back: () => void }) { const [read, setRead] = useState<number[]>(() => readStore('messages-read', [])); const markAllRead = () => { const all = [0,1,2]; localStorage.setItem('messages-read', JSON.stringify(all)); setRead(all); }; const openMessage = (index: number, route: string) => { const next = [...new Set([...read,index])]; localStorage.setItem('messages-read', JSON.stringify(next)); setRead(next); go(route); }; return <Page go={go} className="detail-page messages-page"><Topbar title="站内消息" back={back} action={<button className="text-action" onClick={markAllRead}>全部已读</button>} /><main className="page-gutter message-list">{[['任务提醒','新员工岗位能力提升任务即将到期，请按时完成。','今天 09:30'],['课程更新','新客接待模拟训练已上架，欢迎练习。','昨天 16:20'],['成长报告','本月成长报告已生成，看看你的进步。','10月12日']].map(([title,body,time],i) => <button key={title} onClick={() => openMessage(i, i === 0 ? '/task/task-1' : i === 1 ? '/course/train-1' : '/my/growth')}><span className="message-icon"><Bell size={20} /></span><span><strong>{title}{!read.includes(i) && <i />}</strong><p>{body}</p><small>{time}</small></span><ChevronRight size={17} /></button>)}</main></Page>; }

export default function App() {
  const { path, params, go, back } = useRoute();
  useEffect(() => { document.title = 'ola-training · 鲸智智训'; }, []);
  const seg = path.split('/').filter(Boolean);
  const course = getCourse(seg[1] === 'quiz' || seg[1] === 'rules' || seg[1] === 'result' ? seg[2] : seg[1]);
  const content = useMemo(() => {
    if (path === '/home' || path === '/') return <HomePage go={go} />;
    if (path === '/courses') return <CourseCenter go={go} />;
    if (path === '/tasks') return <TaskCenter go={go} />;
    if (path === '/whale') return <WhaleHome go={go} />;
    if (path === '/my') return <MyPage go={go} />;
    if (seg[0] === 'task') return <TaskDetail key={seg[1]} task={getTask(seg[1])} go={go} back={back} />;
    if (seg[0] === 'course') return <CourseDetail key={seg[1]} course={course} go={go} back={back} />;
    if (seg[0] === 'content') return <LearnContent key={seg[1]} course={course} go={go} back={back} />;
    if (seg[0] === 'training') return <TrainingChat key={seg[1]} course={course} go={go} back={back} />;
    if (seg[0] === 'recap') return <TrainingRecap key={seg[1]} course={course} go={go} back={back} />;
    if (seg[0] === 'exam' && seg[1] === 'rules') return <ExamRules course={course} go={go} back={back} />;
    if (seg[0] === 'exam' && seg[1] === 'quiz') return <ExamQuiz key={seg[2]} course={course} go={go} back={back} />;
    if (seg[0] === 'exam' && seg[1] === 'result') return <ExamResult course={course} score={Number(params.get('score') || 0)} go={go} back={back} />;
    if (seg[0] === 'whale' && seg[1] === 'chat') return <WhaleChat key={`terminal-${params.get('session') || 'main'}`} sessionId={params.get('session') || 'main'} go={go} back={back} />;
    if (seg[0] === 'whale' && seg[1] === 'app') return <WhaleChat key={`${seg[2]}-${params.get('session') || 'main'}`} appId={seg[2]} sessionId={params.get('session') || 'main'} go={go} back={back} />;
    if (seg[0] === 'my' && seg[1] === 'rank') return <RankPage go={go} back={back} />;
    if (seg[0] === 'my' && seg[1] === 'growth') return <GrowthPage go={go} back={back} />;
    if (seg[0] === 'my' && seg[1] === 'history') return <HistoryPage go={go} back={back} />;
    if (seg[0] === 'my' && (seg[1] === 'courses' || seg[1] === 'tasks')) return <StatsPage mode={seg[1]} go={go} back={back} />;
    if (path === '/search') return <SearchPage go={go} back={back} />;
    if (path === '/messages') return <MessagesPage go={go} back={back} />;
    return <Page go={go}><Topbar title="页面未找到" back={back} /><Empty title="暂时找不到这个页面" hint="可以从首页重新开始" action="返回首页" onAction={() => go('/home')} /></Page>;
  }, [path, params.toString()]);
  return <div className="app-shell">{content}</div>;
}
